  hood(g, 12, 12, 12, 6, true);                   // 2nd floor, over the x12 window
  sill(g, 9, 9, 9, 6);
  sill(g, 12, 12, 9, 6);
  hood(g, 9, 9, 15, 6);                           // top floor
  hood(g, 12, 12, 15, 6);
  sill(g, 9, 9, 13, 6);
  sill(g, 12, 12, 13, 6);

  // ---- porch: two quartz columns in the mouth (x10, x13, z7) and the arch spring under the gold porch head -----------------
  column(g, 10, 5, 7, 7);
  column(g, 13, 5, 7, 7);
  archSpring(g, 11, 12, 7, 7);
}

